document.addEventListener("app:route-changed",()=>{const e=[...document.querySelectorAll(".stepwell-card")],t=[...document.querySelectorAll(".journey-bookmark-btn")];window.Journey&&(t.forEach(e=>{const t=e.closest(".stepwell-card");if(!t)return;const r=e.dataset.bookmarkId,o=t.querySelector("h2, h3, h4")?.textContent.trim()||"Item",n=t.querySelector("img")?.getAttribute("src")||"",l=()=>{const t=window.Journey.isSaved(r);e.classList.toggle("is-saved",t),e.setAttribute("aria-pressed",String(t)),e.textContent=t?"♥":"♡"};l(),e.addEventListener("click",e=>{e.stopPropagation(),window.Journey.toggle({id:r,explorerPage:"stepwells.html",title:o,thumbnail:n,category:"stepwells"}),l()})}),window.Journey.registerSearchItems("stepwells.html",e.map(e=>({id:e.dataset.id,title:e.querySelector("h2, h3, h4")?.textContent.trim()||"Item",description:e.querySelector("p")?.textContent.trim()||"",link:"stepwells.html"}))))});